package com.wizzadrds.theworldremembers.voice; import java.io.IOException; import java.nio.file.Path; import java.util.UUID; public final class LocalVoiceRuntime { private final SpeechToTextAdapter stt; private final TextToSpeechAdapter tts; private final VoiceScheduler scheduler; public LocalVoiceRuntime(SpeechToTextAdapter stt,TextToSpeechAdapter tts,VoiceScheduler scheduler){this.stt=stt;this.tts=tts;this.scheduler=scheduler;} public String transcribe(Path audio)throws IOException,InterruptedException{return stt.transcribe(audio);} public boolean queue(UUID npcId,String text,VoicePriority priority,long tick){return scheduler.submit(new VoiceJob(npcId,text,priority,tick));} public Path synthesize(VoiceJob job,VoiceProfile profile,Path output)throws IOException,InterruptedException{return tts.synthesize(job.text(),profile,output);} public VoiceJob next(){return scheduler.startNext();} public void finish(UUID npcId){scheduler.finish(npcId);} }
